import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();
        Map<Long, Long> parentMap = new HashMap<>();
        long answer = 1;
        for (long i = 0; i < p; ++i) {
            parentMap.put(i, i);
        }
        Set<Long> s = new HashSet<>();
        s.add(0);
        if (k == 0) {
            for (long i = 1; i < p; ++i) {
                answer = (answer * p) % 1000000007;
            }
            System.out.println(answer);
            sc.close();
            return;
        }
        for (long i = 0; i < p; ++i) {
            long target = (k * i) % p;
            long root_i = i;
            long root_target = target;
            while (parentMap.get(root_i) != root_i) {
                root_i = parentMap.get(root_i);
            }
            while (parentMap.get(root_target) != root_target) {
                root_target = parentMap.get(root_target);
            }
            parentMap.put(root_i, root_target);
        }
        Map<Long, Integer> count = new HashMap<>();
        for (long i = 0; i < p; ++i) {
            long root = i;
            while (parentMap.get(root) != root) {
                root = parentMap.get(root);
            }
            count.put(root, count.getOrDefault(root, 0) + 1);
        }
        for (Map.Entry<Long, Integer> entry : count.entrySet()) {
            if (entry.getValue() != 0) {
                answer = (answer * p) % 1000000007;
            }
        }
        if (k == 1) {
            answer = (answer * p) % 1000000007;
        }
        System.out.println(answer);
        sc.close();
    }
}
